mapper.select:


     and o.store_id = #{storeId}
     and o.status = #{status}
     and o.order_number like concat('%', #{orderNumber}, '%')
     and o.date_created >= #{params.beginTime}
     and o.date_created <= concat(#{params.endTime}, ' 23:59:59')

order by o.date_created desc, o.order_id desc
